<?php
declare(strict_types=1); require_once __DIR__.'/../includes/functions.php'; require_admin();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('admin/walkin-rental.php');verify_csrf();$type=post('customer_type');$uid=(int)post('user_id')?:null;$name=post('walkin_name')?:null;$phone=post('walkin_phone')?:null;$bookId=(int)post('book_id');$days=(int)post('rental_days');if(!valid_days($days)||!in_array($type,['member','walkin'],true)||($type==='member'&&!$uid)||($type==='walkin'&&(!$name||!$phone))){flash('กรุณากรอกข้อมูลลูกค้า หนังสือ และระยะเวลาให้ครบ','error');redirect('admin/walkin-rental.php');}$pdo=db();try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT * FROM books WHERE id=? AND status='available' FOR UPDATE");$s->execute([$bookId]);$b=$s->fetch();if(!$b)throw new RuntimeException('หนังสือไม่พร้อมให้เช่า');$due=date('Y-m-d',strtotime("+$days days"));$total=rental_fee((float)$b['rental_price_per_day'],$days);$pdo->prepare("INSERT INTO rentals(user_id,walkin_name,walkin_phone,book_id,source,rental_days,rental_price_per_day_at_time,rental_total,borrowed_at,due_date,status) VALUES(?,?,?,?,'walkin',?,?,?,NOW(),?,'borrowed')")->execute([$type==='member'?$uid:null,$type==='walkin'?$name:null,$type==='walkin'?$phone:null,$bookId,$days,$b['rental_price_per_day'],$total,$due]);$id=(int)$pdo->lastInsertId();$pdo->prepare("UPDATE books SET status='borrowed' WHERE id=?")->execute([$bookId]);log_activity('create','rental',$id);$pdo->commit();flash('เริ่มการเช่าหน้าร้านสำเร็จ กำหนดคืน '.thai_date($due));}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e->getMessage(),'error');}redirect('admin/walkin-rental.php');
